        "@@ author = \"Mettrich\"",
        "@@ filler1 = 0xbbbbbbff",
        "@@ filler2 = 0xbbbbffff",
        "@@ filler3 = 0xbbffffff",
        "@@ filler4 = 0xffffffff",
        "@@ fill = false",
        "; Requirements:",
        "; - any (meta)stable ACE species",
        ";",
        "; Credit to sleipnir17 for the addresses of the script!",
        "@@",
        "bicgt r10, r13, #0xbf000",
        "0xc1bfc9ce ; movgts r12, r14, asr #19",
        "mov r11, #0x3fc00",
        "strh r12, [r10, #0x35]!",
        "strgtb r15, [r5], #0xfff",
        "strgth r12, [r10, #0x8]",
        "; put the script pointer in r12",
        "adcgts r12, r11, #0x0c600000",
        "adcgts r12, r12, #0x00035c00",
        "sbcgt r12, r12, #0x0000000b",
        "bicgt r11, r14, #0xff00",
        "strge r12, [r10, r14, asr #23]!",
        "adcgts r15, r11, #0x2b0"
